<?php
namespace App\Http\Controllers;
use App\Models\{AcademicSession,SchoolClass,Subject,SubjectGroup,TeacherProfile,User};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;

class CurriculumManagementController extends Controller {
 private function admin(Request $r):void {abort_unless($r->user()->is_active && $r->user()->hasAnyRole(['super_admin','school_admin']) && $r->user()->can('subjects.manage'),403);}
 private function coordinator(Request $r,int $subjectId):void {
  if($r->user()->is_active && $r->user()->hasRole('super_admin')) return;
  $id=$r->user()->teacherProfile?->id;
  abort_unless($r->user()->is_active && $id && DB::table('subject_coordinator_assignments')->where('subject_id',$subjectId)->where('teacher_profile_id',$id)->where('status','active')->exists(),403);
 }
 private function audit(Request $r,string $module,string $action,int $id,array $old=[],array $new=[]):void {
  DB::table('audit_logs')->insert(['actor_user_id'=>$r->user()->id,'actor_identifier'=>$r->user()->email,'actor_role_snapshot'=>$r->user()->getRoleNames()->implode(', '),'event_category'=>'academic_management','action'=>$action,'module'=>$module,'auditable_type'=>'curriculum','auditable_id'=>$id,'old_values'=>json_encode($old),'new_values'=>json_encode($new),'metadata'=>null,'ip_address'=>$r->ip(),'user_agent'=>$r->userAgent(),'request_id'=>$r->header('X-Request-ID')??(string)Str::uuid(),'outcome'=>'success','created_at'=>now()]);
 }
 public function index(Request $r){abort_unless($r->user()->is_active && $r->user()->can('subjects.view'),403);
  $groups=SubjectGroup::orderBy('name')->get();$subjects=Subject::with('subjectGroup')->orderBy('name')->get();$sessions=AcademicSession::orderByDesc('start_date')->get();$classes=SchoolClass::with('academicSession')->orderBy('name')->get();$teachers=TeacherProfile::where('status','active')->orderBy('full_name')->get();
  $classSubjects=DB::table('class_subjects')->get()->groupBy('class_id');$coordinators=DB::table('subject_coordinator_assignments')->get();$syllabuses=DB::table('subject_syllabuses')->orderByDesc('id')->get();$links=DB::table('academic_session_syllabuses')->get();$topics=DB::table('subject_syllabus_topics')->orderBy('semester_number')->orderBy('sort_order')->get();
  $canAdmin=$r->user()->is_active && $r->user()->hasAnyRole(['super_admin','school_admin']) && $r->user()->can('subjects.manage');
  $editableSubjectIds=$r->user()->hasRole('super_admin') ? $subjects->pluck('id')->all() : DB::table('subject_coordinator_assignments')->where('teacher_profile_id',$r->user()->teacherProfile?->id ?? 0)->where('status','active')->pluck('subject_id')->all();
  return view('curriculum.index',compact('groups','subjects','sessions','classes','teachers','classSubjects','coordinators','syllabuses','links','topics','canAdmin','editableSubjectIds'));
 }
 public function group(Request $r){$this->admin($r);$v=$r->validate(['code'=>['required','string','max:30',Rule::unique('subject_groups','code')],'name'=>'required|string|max:150','description'=>'nullable|string|max:1000']);$o=DB::transaction(function()use($v,$r){$o=SubjectGroup::create($v+['is_active'=>true]);$this->audit($r,'subject_groups','create',$o->id,[],$o->toArray());return $o;});return back()->with('success','Subject group created.');}
 public function subject(Request $r){$this->admin($r);$v=$r->validate(['code'=>['required','string','max:30',Rule::unique('subjects','code')],'name'=>'required|string|max:150','subject_group_id'=>'nullable|exists:subject_groups,id','description'=>'nullable|string|max:1000']);DB::transaction(function()use($r,$v){$s=Subject::create($v+['is_active'=>true]);$this->audit($r,'subjects','create',$s->id,[],$s->toArray());});return back()->with('success','Subject created.');}
 public function status(Request $r,string $type,int $id){$this->admin($r);abort_unless(in_array($type,['subjects','subject_groups']),404);$v=$r->validate(['is_active'=>'required|boolean']);$model=$type==='subjects'?Subject::class:SubjectGroup::class;DB::transaction(function()use($r,$model,$type,$id,$v){$m=$model::findOrFail($id);$old=$m->toArray();$m->update(['is_active'=>(bool)$v['is_active']]);$this->audit($r,$type,'change_status',$id,$old,$m->toArray());});return back()->with('success','Status updated.');}
 public function combination(Request $r,SchoolClass $schoolClass){$this->admin($r);$v=$r->validate(['subject_ids'=>'required|array|min:1','subject_ids.*'=>'integer|distinct|exists:subjects,id']);$ids=array_map('intval',$v['subject_ids']);$active=Subject::whereIn('id',$ids)->where('is_active',true)->count();if($active!==count($ids))throw ValidationException::withMessages(['subject_ids'=>'Select active subjects only.']);
  DB::transaction(function()use($r,$schoolClass,$ids){$old=DB::table('class_subjects')->where('class_id',$schoolClass->id)->pluck('subject_id')->all();$removed=array_diff($old,$ids);if($removed && (DB::table('student_class_enrollments')->where('class_id',$schoolClass->id)->exists() || DB::table('teacher_subject_class')->where('class_id',$schoolClass->id)->whereIn('subject_id',$removed)->exists()))throw ValidationException::withMessages(['subject_ids'=>'Existing student enrollment or teacher assignment prevents removing subjects.']);DB::table('class_subjects')->where('class_id',$schoolClass->id)->whereNotIn('subject_id',$ids)->delete();foreach($ids as $id)DB::table('class_subjects')->updateOrInsert(['class_id'=>$schoolClass->id,'subject_id'=>$id],['updated_at'=>now(),'created_at'=>now()]);$this->audit($r,'class_subjects','sync',$schoolClass->id,['subject_ids'=>$old],['subject_ids'=>$ids]);});return back()->with('success','Fixed subject combination saved.');}
 public function assignCoordinator(Request $r){
  $this->admin($r);
  $v=$r->validate(['subject_id'=>'required|exists:subjects,id','teacher_profile_id'=>'required|exists:teacher_profiles,id']);
  $t=TeacherProfile::with('user')->findOrFail($v['teacher_profile_id']);
  if ($t->status !== 'active' || !$t->user?->is_active || !Subject::whereKey($v['subject_id'])->where('is_active',true)->exists())
   throw ValidationException::withMessages(['teacher_profile_id'=>'Choose an active teacher and subject.']);
  DB::transaction(function()use($r,$v){
   $old=DB::table('subject_coordinator_assignments')->where('subject_id',$v['subject_id'])->lockForUpdate()->first();
   $values=['teacher_profile_id'=>$v['teacher_profile_id'],'status'=>'active','updated_at'=>now()];
   if($old) DB::table('subject_coordinator_assignments')->where('id',$old->id)->update($values);
   else DB::table('subject_coordinator_assignments')->insert(['subject_id'=>$v['subject_id']]+$values+['created_at'=>now()]);
   $this->audit($r,'subject_coordinator_assignments','appoint',(int)$v['subject_id'],(array)($old??[]),$v);
  });
  return back()->with('success','Global subject coordinator appointed.');
 }
 public function syllabus(Request $r){$v=$r->validate(['subject_id'=>'required|exists:subjects,id','version'=>'required|string|max:80','title'=>'required|string|max:200','reference_url'=>'nullable|url|max:2000']);$this->coordinator($r,(int)$v['subject_id']);$exists=DB::table('subject_syllabuses')->where('subject_id',$v['subject_id'])->where('version',$v['version'])->exists();if($exists)throw ValidationException::withMessages(['version'=>'Version already exists for this subject.']);DB::transaction(function()use($r,$v){$id=DB::table('subject_syllabuses')->insertGetId($v+['status'=>'draft','created_at'=>now(),'updated_at'=>now()]);$this->audit($r,'subject_syllabuses','create',$id,[],$v);});return back()->with('success','Syllabus version created.');}
 public function linkSyllabus(Request $r){$this->admin($r);$v=$r->validate(['academic_session_id'=>'required|exists:academic_sessions,id','subject_syllabus_id'=>'required|exists:subject_syllabuses,id']);$sy=DB::table('subject_syllabuses')->find($v['subject_syllabus_id']);DB::transaction(function()use($r,$v,$sy){$old=DB::table('academic_session_syllabuses')->where('academic_session_id',$v['academic_session_id'])->where('subject_id',$sy->subject_id)->first();if($old && (DB::table('student_class_enrollments')->where('academic_session_id',$v['academic_session_id'])->exists()))throw ValidationException::withMessages(['subject_syllabus_id'=>'Syllabus is locked after student enrollment.']);DB::table('academic_session_syllabuses')->updateOrInsert(['academic_session_id'=>$v['academic_session_id'],'subject_id'=>$sy->subject_id],['subject_syllabus_id'=>$sy->id,'updated_at'=>now(),'created_at'=>now()]);$this->audit($r,'academic_session_syllabuses','assign',(int)$v['academic_session_id'],(array)($old??[]),['subject_syllabus_id'=>$sy->id]);});return back()->with('success','Intake syllabus linked.');}
 private function context(Request $r,int $syllabusId):object {
  $sy=DB::table('subject_syllabuses')->find($syllabusId);
  abort_unless($sy,404);
  $this->coordinator($r,(int)$sy->subject_id);
  return $sy;
 }
 public function topic(Request $r){$v=$r->validate(['subject_syllabus_id'=>'required|exists:subject_syllabuses,id','semester_number'=>'required|integer|between:1,3','parent_id'=>'nullable|exists:subject_syllabus_topics,id','title'=>'required|string|max:200','description'=>'nullable|string|max:5000','learning_objectives'=>'nullable|string|max:5000','sort_order'=>'nullable|integer|min:0']);$sy=$this->context($r,(int)$v['subject_syllabus_id']);if(isset($v['parent_id']) && !DB::table('subject_syllabus_topics')->where('id',$v['parent_id'])->where('subject_syllabus_id',$sy->id)->where('semester_number',$v['semester_number'])->exists())throw ValidationException::withMessages(['parent_id'=>'Parent topic must belong to the same syllabus and semester.']);DB::transaction(function()use($r,$v){$id=DB::table('subject_syllabus_topics')->insertGetId(['subject_syllabus_id'=>$v['subject_syllabus_id'],'semester_number'=>$v['semester_number'],'parent_id'=>$v['parent_id']??null,'title'=>$v['title'],'description'=>$v['description']??null,'learning_objectives'=>$v['learning_objectives']??null,'sort_order'=>$v['sort_order']??0,'status'=>'draft','created_at'=>now(),'updated_at'=>now()]);$this->audit($r,'subject_syllabus_topics','create',$id,[],$v);});return back()->with('success','Draft topic added.');}
 public function editTopic(Request $r,int $id){$v=$r->validate(['title'=>'required|string|max:200','description'=>'nullable|string|max:5000','learning_objectives'=>'nullable|string|max:5000','sort_order'=>'required|integer|min:0']);$topic=DB::table('subject_syllabus_topics')->find($id);abort_unless($topic,404);$this->context($r,$topic->subject_syllabus_id);if($topic->status==='published')throw ValidationException::withMessages(['title'=>'Published topic cannot be edited in place. Create a new version to preserve teacher visibility.']);DB::transaction(function()use($r,$id,$v){$old=DB::table('subject_syllabus_topics')->where('id',$id)->lockForUpdate()->first();DB::table('subject_syllabus_topic_revisions')->insert(['topic_id'=>$id,'edited_by'=>$r->user()->id,'snapshot'=>json_encode($old),'created_at'=>now(),'updated_at'=>now()]);DB::table('subject_syllabus_topics')->where('id',$id)->update(['title'=>$v['title'],'description'=>$v['description']??null,'learning_objectives'=>$v['learning_objectives']??null,'sort_order'=>$v['sort_order'],'status'=>'draft','published_at'=>null,'published_by'=>null,'updated_at'=>now()]);$this->audit($r,'subject_syllabus_topics','update',$id,(array)$old,$v);});return back()->with('success','Topic updated as draft; publish again to release changes.');}
 public function publish(Request $r,int $id){$v=[];$topic=DB::table('subject_syllabus_topics')->find($id);abort_unless($topic,404);$sy=$this->context($r,$topic->subject_syllabus_id);DB::transaction(function()use($r,$id,$sy){$old=DB::table('subject_syllabus_topics')->where('id',$id)->lockForUpdate()->first();DB::table('subject_syllabus_topic_revisions')->insert(['topic_id'=>$id,'edited_by'=>$r->user()->id,'snapshot'=>json_encode($old),'created_at'=>now(),'updated_at'=>now()]);DB::table('subject_syllabus_topics')->where('id',$id)->update(['status'=>'published','published_by'=>$r->user()->id,'published_at'=>now(),'updated_at'=>now()]);DB::table('subject_syllabuses')->where('id',$sy->id)->update(['status'=>'published','published_by'=>$r->user()->id,'published_at'=>now(),'updated_at'=>now()]);$this->audit($r,'subject_syllabus_topics','publish',$id,(array)$old,['status'=>'published']);});return back()->with('success','Topic immediately published to assigned teachers.');}
}
